      EXECUTE format('GRANT UPDATE (name) ON auth.location TO %I', a);
      EXECUTE format('GRANT SELECT ON auth.location TO %I', l);
      EXECUTE format('GRANT SELECT, INSERT, UPDATE ON auth.location_login_config TO %I', a);
